-- CampBuddy — Gemeindeflächen.
--
-- 2119 Gemeinden, davon 2102 mit Kontakt.
-- Nur Geometrie und Kontakt; die Rechtslage steht in gemeinden.legal.json.
--
-- Voraussetzung: 0013_gemeinden.sql ist gelaufen.
-- Teil 6 von 8.

begin;
on conflict (id) do update set bfs = excluded.bfs, name = excluded.name, kanton = excluded.kanton, website = excluded.website, email = excluded.email, source_url = excluded.source_url, geometry = excluded.geometry, updated_at = now();
commit;
